+    torch::stable::Tensor const& positions,  // [N] i64
+    int64_t num_heads, int64_t num_kv_heads, int64_t head_dim, double eps,
+    std::optional<torch::stable::Tensor> cos_sin_cache,  // None => NoPE layer
